import React, { useState, useEffect, useRef } from 'react';
import './Time_Widget.css';

/**
 * TimeWidget Component
 * 
 * Replicates the futuristic time widget from splash_screen.html.
 * Features:
 * - Real-time clock with second-tick animation
 * - Draggable and Scalable interface
 * - Glassmorphism design with corner accents
 * - Location display support
 */
const TimeWidget = ({ onClose, initialPosition = { x: 100, y: 100 }, location = "Local Time" }) => {
    const [time, setTime] = useState(new Date());
    const [position, setPosition] = useState(initialPosition);
    const [isDragging, setIsDragging] = useState(false);
    const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
    const [scale, setScale] = useState(1);

    // Animation states
    const [isFlashing, setIsFlashing] = useState(false);
    const [isTicking, setIsTicking] = useState(false);

    const widgetRef = useRef(null);

    // Initial Flash when location changes or component mounts
    useEffect(() => {
        setIsFlashing(true);
        const timer = setTimeout(() => setIsFlashing(false), 800);
        return () => clearTimeout(timer);
    }, [location]);

    // Update time every second
    useEffect(() => {
        const timer = setInterval(() => {
            setTime(new Date());

            // Subtle tick animation each second
            setIsTicking(true);
            setTimeout(() => setIsTicking(false), 200);

        }, 1000);
        return () => clearInterval(timer);
    }, []);

    // Handle Dragging
    const handleMouseDown = (e) => {
        // Prevent dragging if clicking on controls or resize handle
        if (e.target.closest('.widget-controls') || e.target.closest('.resize-handle')) {
            return;
        }

        if (widgetRef.current) {
            const rect = widgetRef.current.getBoundingClientRect();
            setDragOffset({
                x: e.clientX - rect.left,
                y: e.clientY - rect.top
            });
            setIsDragging(true);
        }
    };

    useEffect(() => {
        const handleMouseMove = (e) => {
            if (isDragging) {
                // Calculate new position
                const newX = e.clientX - dragOffset.x;
                const newY = e.clientY - dragOffset.y;

                // Optional: Add simple bounds checking here if needed

                setPosition({ x: newX, y: newY });
            }
        };

        const handleMouseUp = () => {
            setIsDragging(false);
        };

        if (isDragging) {
            document.addEventListener('mousemove', handleMouseMove);
            document.addEventListener('mouseup', handleMouseUp);
        }

        return () => {
            document.removeEventListener('mousemove', handleMouseMove);
            document.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, dragOffset]);

    // Handle Resize (Scaling)
    const handleIncreaseSize = () => {
        setScale(prev => Math.min(prev + 0.1, 2));
    };

    const handleDecreaseSize = () => {
        setScale(prev => Math.max(prev - 0.1, 0.5));
    };

    // Format Time: 12-hour format with AM/PM (or 24h if preferred, but usually widgets look cool with 24h or clear AM/PM)
    // The original splash_screen used standard locale time string.
    const formatTime = (date) => {
        return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
    };

    return (
        <div
            ref={widgetRef}
            className="time-display"
            style={{
                left: `${position.x}px`,
                top: `${position.y}px`,
                transform: `scale(${scale})`
            }}
            onMouseDown={handleMouseDown}
        >
            {/* Corner Brackets */}
            <div className="corner-top-right"></div>
            <div className="corner-bottom-left"></div>

            {/* Widget Controls */}
            <div className="widget-controls">
                <div className="widget-control-btn" onClick={handleIncreaseSize} title="Make Bigger">⧨</div>
                <div className="widget-control-btn" onClick={handleDecreaseSize} title="Make Smaller">⧩</div>
                <div className="widget-control-btn" onClick={onClose} title="Close">✕</div>
            </div>

            {/* Resize Handle (Visual only for now, functionality via buttons) */}
            <div className="resize-handle"></div>

            {/* Content */}
            <div className="time-label">TIME</div>
            <div className={`time-value ${isFlashing ? 'flash' : ''} ${isTicking ? 'tick' : ''}`}>
                {formatTime(time)}
            </div>
            <div className="time-location">{location}</div>
        </div>
    );
};

export default TimeWidget;
